/* 第 2 页（纯数字栅格）：8 格值，等宽右对齐；暂停时数字退灰。 */
static void ride_refresh_grid(void)
{
    char b[8][24];
    const uint32_t ink = R.paused ? P_TRACK : P_INK;

    if (UR.gv[0] == NULL) {
        return;
    }
    snprintf(b[0], sizeof(b[0]), "%.1f", conv_speed(R.speed));
    snprintf(b[1], sizeof(b[1]), "%.1f", conv_speed(R.avg));
    snprintf(b[2], sizeof(b[2]), "%.1f", conv_dist(R.dist_km));
    snprintf(b[3], sizeof(b[3]), "%u:%02u",
             (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60));
    snprintf(b[4], sizeof(b[4]), "%d", R.hr);
    snprintf(b[5], sizeof(b[5]), "%d", R.cadence);
    snprintf(b[6], sizeof(b[6]), "%d", R.elevation);
    snprintf(b[7], sizeof(b[7]), "%+.1f", grade_val(R.grade));
    for (int i = 0; i < 8; i++) {
        lv_label_set_text(UR.gv[i], b[i]);
        lv_obj_set_style_text_color(UR.gv[i], lv_color_hex(ink), 0);
    }
}

/* 第 3 页（全屏地图）：速度大字 + 转向提示 + 已骑里程。 */
static void ride_refresh_map(void)
{
    char buf[32];

    if (UR.map_speed == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%.1f", conv_speed(R.speed));
    lv_label_set_text(UR.map_speed, buf);
    lv_obj_set_style_text_color(UR.map_speed,
                                lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    if (UR.map_unit != NULL) {
        lv_label_set_text(UR.map_unit, unit_speed());
        /* 单位紧跟数值（36px 字形的 advance + 4px），随位数变化重排。 */
        lv_obj_set_x(UR.map_unit, 14 + text_width(buf, 36) + 4);
    }
    if (UR.map_turn != NULL) {
        const int m = 480 - (int)(R.elapsed_s * 10) % 480;

        snprintf(buf, sizeof(buf), "%d m", ((m <= 0 ? 480 : m) / 10) * 10);
        lv_label_set_text(UR.map_turn, buf);
        lv_label_set_text(UR.map_turn_sub, NAV_TURNS[s_nav_turn % 4]);
    }
    if (UR.map_dist != NULL) {
        snprintf(buf, sizeof(buf), "已骑 %.1f %s", conv_dist(R.dist_km),
                 unit_dist());
        lv_label_set_text(UR.map_dist, buf);
    }
}

