/* 骑行页入口：三页各自独立构建（不轮转的页内布局），KEY 左右切换。 */
static void ride_build(void)
{
    memset(&UR, 0, sizeof(UR));
    d_bg(s_scr, P_PAPER);
    if (s_ride_page == 1) {
        statusbar_build();
        ride_build_grid();
        ride_page_dots();
    } else if (s_ride_page == 2) {
        ride_build_map();       /* 内部：地图（y=24 起）+ 状态栏 + 页点 + 浮层 */
