static void lp_fire(void)
{
    lp_target_t target = LP.target;

    keylog("KEY%d long fired (target=%d) screen=%s", LP.key, (int)target,
           SCR_NAME[s_screen]);
    LP.active = false;
    switch (target) {
        case LP_ENTER:
            if (UD.unit != NULL) {
                lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
            }
            enter_selected_mode();
            break;
        case LP_ACTIVATE:
            setl_activate();
            break;
        case LP_PAUSE:
            if (!R.active) {
                ride_start();
                s_screen = SCR_RIDE;
                s_busy = false;
                rebuild();
            } else {
                R.paused = !R.paused;
                R.auto_paused = false;
                R.still_s = 0;
                if (R.paused) {
                    R.speed = 0.0;
                    R.cadence = 0;
                    R.power = 0;
                }
                s_busy = false;
                rebuild();
            }
            break;
        case LP_BACK:
            /* 骑行页左长按返回环形页：本次记录继续（不停表）。 */
            keylog("KEY%d long -> back (record continues)", LP.key);
            go_back();
            break;
        case LP_NAV_CTRL:
            if (s_nav_active) {
                s_sub_sel = 0;
                s_screen = SCR_NAV_LIVE;
            } else {
                s_screen = SCR_ELEVATION;
            }
            s_busy = false;
            rebuild();
            break;
        case LP_GRADE_ZERO:
            s_grade_off_x10 = -42;
            toast("坡度已归零");
            s_busy = false;
            rebuild();
            break;
        case LP_TOGGLE_RIDE:
            if (UD.unit != NULL) {
                lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
            }
            toggle_ride();
            if (s_screen == SCR_DIAL || s_screen == SCR_RIDE) {
                rebuild();
            }
            break;
        default:
            break;
    }
}

