static void modal_action(int key)
{
    switch (s_modal) {
        case MODAL_SHUTDOWN:
            s_modal = MODAL_NONE;
            if (key == 1) {
                keylog("modal shutdown: cancel");
                s_busy = false;
                rebuild();
            } else {
