/** 最近 60 s 假心率序列的统计：均值四舍五入、峰值取最大值。
 *
 *  v[i] = clamp(R.hr + s_hr_delta[i], 60, 200)，i = 0..30；
 *  mean = (Σv + N/2) / N（整数除法 = 四舍五入）；
 *  peak = max(v)。
 *  例：R.hr = 148 时 Σv = 31·148 − 466 = 4122，
 *  mean = (4122 + 15)/31 = 4137/31 = 133，peak = 148 + 0 = 148。 */
static void hr_hist_stats(int *avg, int *peak)
{
    int sum = 0;
    int mx = -1000;

    for (int i = 0; i < HR_HIST_N; i++) {
        int v = R.hr + s_hr_delta[i];

        if (v < HR_MIN_BPM) v = HR_MIN_BPM;
        if (v > HR_MAX_BPM) v = HR_MAX_BPM;
        sum += v;
        if (v > mx) mx = v;
    }
    *avg = (sum + HR_HIST_N / 2) / HR_HIST_N;
    *peak = mx;
}

